--
-- Table structure for table `retailer_orders`
--

DROP TABLE IF EXISTS `retailer_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `retailer_orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `deletedAt` datetime DEFAULT NULL,
  `isApproved` tinyint NOT NULL DEFAULT '0',
  `is_stock_order` tinyint NOT NULL DEFAULT '0',
  `admin_us_size` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `orderStatus` enum('Pattern','Khaka','Issue Beading','Beading','Zarkan','Stitching','Repair','Balance Pending','Ready To Delivery','Shipped') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pattern',
  `shippingStatus` enum('Not Shipped','Shipped') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Not Shipped',
  `shippingDate` datetime DEFAULT NULL,
  `purchaseAmount` int NOT NULL,
  `shippingAmount` int NOT NULL DEFAULT '0',
  `status_id` int NOT NULL DEFAULT '0',
  `purchaeOrderNo` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `pattern` datetime DEFAULT CURRENT_TIMESTAMP,
  `khaka` datetime DEFAULT NULL,
  `issue_beading` datetime DEFAULT NULL,
  `beading` datetime DEFAULT NULL,
  `zarkan` datetime DEFAULT NULL,
  `stitching` datetime DEFAULT NULL,
  `repair` datetime DEFAULT NULL,
  `ready_to_delivery` datetime DEFAULT NULL,
  `shipped` datetime DEFAULT NULL,
  `shiping_date` datetime DEFAULT NULL,
  `invoiceNo` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estimateNo` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manufacturingEmailAddress` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'rubyinc@hotmail.com',
  `orderReceivedDate` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `orderCancellationDate` datetime DEFAULT NULL,
  `address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `trackingNo` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `StyleNo` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Size` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `size_country` varchar(225) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` int NOT NULL DEFAULT '0',
  `retailerId` int DEFAULT NULL,
  `favouriteOrderId` int DEFAULT NULL,
  `stockOrderId` int DEFAULT NULL,
  `ppt_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Pending',
  `balance_pending` datetime DEFAULT NULL,
  `phoneNumber` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `REL_718fe8f142ff4d322939836d0c` (`stockOrderId`),
  KEY `FK_49149394a7d518c96ee5b797a32` (`retailerId`),
  CONSTRAINT `FK_49149394a7d518c96ee5b797a32` FOREIGN KEY (`retailerId`) REFERENCES `retailers` (`id`),
  CONSTRAINT `FK_718fe8f142ff4d322939836d0c6` FOREIGN KEY (`stockOrderId`) REFERENCES `retailer_stock_orders` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=158 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

